#!/usr/bin/env bash
# Generated by `factory init`. Runs this project's dispatcher against Factory's shared run state, so a
# hand-started pass shows on the Factory board. All arguments go to dispatch.sh.
#   .sandcastle/factory-dispatch.sh [--dry-run] [--max N] [--whole-issues]
# SANDCASTLE_STATE_DIR from the caller wins; otherwise the Factory state folder below is used.
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd -P)"
cd "$root"
if [ -z "${SANDCASTLE_STATE_DIR:-}" ]; then export SANDCASTLE_STATE_DIR='/home/mark/.local/state/factory'; fi
exec "$root/.sandcastle/dispatch.sh" "$@"
